/* Page-local notation, algorithm-specific explanations, and deeper comparisons. */
const COMM_NOTATION = [['P','number of ranks (participants) in this process group; P = 4 in the diagrams'],['r','a rank index, from 0 to P − 1; the root is rank 0 in rooted examples'],['xᵣ, yᵣ','rank r’s input tensor and defined output tensor'],['⊕','an associative elementwise reduction; these examples use SUM'],['α','startup time per communication round / message in the simplified model'],['β','transfer time per byte: β = 1 / effective bandwidth'],['N','tensor size in bytes; its exact meaning is stated for the selected algorithm'],['L','log₂P for the power-of-two examples; use ceiling / adjusted schedules otherwise']];
const ALGORITHM_LESSONS = {
 'all-reduce':{
  Ring:{cost:'T ≈ 2(P−1)α + 2(P−1)Nβ/P',costNote:'N is the full input tensor size on each rank. P−1 reduce-scatter rounds plus P−1 all-gather rounds. Sent payload per rank is 2(P−1)N/P bytes; receive volume is the same.',steps:[['Partition and reduce','Divide each rank’s N-byte tensor into P equal shards. In round k, each rank sends one current partial shard to its clockwise neighbor and reduces the incoming shard.'],['Complete one shard per owner','After P−1 rounds, every input has contributed once to each shard, and each rank owns one fully reduced shard. Forwarded partials are no longer its output.'],['Replicate the reduced shards','AllGather circulates completed shards for another P−1 rounds. This phase copies values; it does not sum them again.']],extra:'At P = 4, there are 6 communication rounds, each carrying N/4 bytes per rank. With N = 1 MiB, α = 2 μs and 1/β = 50 GB/s, this idealized model gives 43.46 μs, excluding reduction compute, contention, and protocol overhead.'},
  Tree:{cost:'T ≈ 2Lα + 2LNβ',costNote:'N is the full input tensor size per rank. This is the illustrated full-tensor reduce-to-root followed by a broadcast, not a chunked NCCL double-tree. Each phase has L full-message rounds; local reduction work is omitted.',steps:[['Reduce across the first level','Ranks 1 → 0 and 3 → 2 transfer complete tensors. Parents add matching positions, forming two partial sums in parallel.'],['Finish at the root','Rank 2 sends its partial sum to rank 0. After L reduction levels, the root holds the full reduced tensor.'],['Broadcast down the tree','Reverse the tree’s reachability to copy the root result to every rank in L more rounds. The mathematical answer matches Ring; traffic placement and reduction order differ.']],extra:'At P = 4, the illustrated tree uses 4 full-message rounds. Under the same hypothetical N = 1 MiB, α = 2 μs and 50 GB/s model, it gives 91.89 μs. Optimized chunked/double trees have different bandwidth costs; “tree” alone does not specify a cost model.'}},
 'all-gather':{
  Ring:{cost:'T ≈ (P−1)α + (P−1)Nβ/P',costNote:'N is the complete gathered tensor size, not the local shard. Each rank starts with N/P bytes, sends one shard per round, and receives the other P−1 shards.',steps:[['Place the owned shard','Each rank places its local N/P-byte input in the rank-ordered output slot.'],['Forward one shard per round','Send the most recently available shard to the next rank. Distinct shards circulate together; nothing is numerically reduced.'],['Finish a replicated tensor','After P−1 rounds, every rank has every source shard. Four ranks reconstruct [A, B, C, D] in three rounds.']],extra:'Good bandwidth utilization does not imply low startup latency: a long ring still pays P−1 dependent rounds.'},
  'Recursive doubling':{cost:'T ≈ Lα + (P−1)Nβ/P',costNote:'N is the complete gathered output size. For power-of-two P, the exchanged payload grows N/P, 2N/P, …, N/2 bytes; the geometric sum is (P−1)N/P.',steps:[['Exchange with XOR distance 1','Ranks 0↔1 and 2↔3 exchange their local shards. Each now knows two shards.'],['Double the known set','At distance 2, each rank exchanges its two known shards with rank r XOR 2. Further distances are powers of two.'],['Restore rank order','Keep shards indexed by original source. At P = 4, two rounds produce the same output as the three-round ring.']],extra:'Logarithmic rounds can help small messages. Larger simultaneous exchanges and distant partner links change contention and topology behavior.'}},
 'reduce-scatter':{
  Ring:{cost:'T ≈ (P−1)α + (P−1)Nβ/P',costNote:'N is the full input tensor size per rank. The output is N/P bytes per rank. Local addition time is omitted.',steps:[['Align corresponding positions','All inputs describe the same N-byte tensor layout and have P equal shards. Color identifies tensor position, not source rank.'],['Forward partial sums','Exchange and add a different partial shard each round. The demo orders the chunks so the final owner of shard r is rank r.'],['Retain one final shard','After P−1 rounds, rank r holds its fully reduced output slice. There is no final AllGather in this operation.']],extra:'The example returns [10], [20], [30], [40] to ranks 0–3. It has the same sum as AllReduce but keeps the result partitioned.'},
  'Recursive halving':{cost:'T ≈ Lα + (P−1)Nβ/P',costNote:'N is the full input size per rank. Exchanged ranges shrink N/2, N/4, …, N/P bytes. The displayed power-of-two schedule assumes equal shards and SUM.',steps:[['Keep complementary halves','At XOR distance 2, partner ranks exchange complementary halves and reduce the half each retains. The other half is discarded from that rank’s result.'],['Halve the range again','At XOR distance 1, exchange half of the remaining range. The retained range shrinks from two shards to one.'],['Use the owner’s output','After L rounds, rank r owns reduced shard r. Non-power-of-two groups need adjusted participation schedules.']],extra:'This trades the ring’s P−1 dependent rounds for log₂P rounds, while retaining the same idealized payload volume per rank.'}},
 broadcast:{
  'Binomial tree':{cost:'T ≈ L(α + Nβ)',costNote:'N is the root’s tensor size. This unsegmented example forwards the full N bytes at each of L levels. Actual tree fanout, link sharing, and receiver scheduling can change time.',steps:[['Agree on the source','Root rank 0 supplies the only input. Every receiver has a compatible count, datatype, and destination buffer.'],['Double the informed group','First 0 → 1; then 0 → 2 and 1 → 3. A participant forwards only after obtaining the root data.'],['Expose identical copies','Every output is [A, B, C, D]. Other ranks’ initial buffer contents have not contributed to the result.']],extra:'For P = 4 this full-message tree has two levels. Broadcast is not AllGather: there is only one source tensor.'},
  'Pipelined tree':{cost:'Ideal pipeline: T ≈ (K + h − 1)(α + Nβ/K)',costNote:'N is root input bytes, K is the number of chunks (4 here), and h is tree depth (2 here). The illustrative bound assumes independent tree links and one chunk per edge per tick; fanout contention is excluded.',steps:[['Segment the root tensor','Split [A, B, C, D] into K chunks. A receiver can forward a completed chunk before receiving the entire tensor.'],['Pipeline dependency-safe hops','At tick t, root sends the next chunk to ranks 1 and 2 while rank 1 forwards the previous chunk to rank 3. No chunk crosses two tree levels in one tick.'],['Drain the final chunk','The last chunk still needs to reach the deepest leaf. K + h − 1 logical ticks fill and drain this pipeline.']],extra:'Small chunks start forwarding early but pay more startup costs. Large chunks amortize startup but delay the pipeline’s first downstream transfer.'}},
 reduce:{
  Tree:{cost:'T ≈ L(α + Nβ)',costNote:'N is each rank’s full input tensor size. The full-tensor tree has L reduction levels; arithmetic time is not included.',steps:[['Pair the contributors','Ranks 1 → 0 and 3 → 2 send their full tensors, and parents add corresponding elements.'],['Merge partial reductions','Rank 2 sends its partial result to rank 0. No source contribution is counted twice.'],['Read only the root output','The root receives [10, 20, 30, 40]. Non-root receive buffers have no defined reduced output under this operation.']],extra:'Partial results need an associative operator. For a noncommutative operator, a valid algorithm must also preserve operand order.'},
  Linear:{cost:'T ≈ (P−1)(α + Nβ)',costNote:'N is the full tensor bytes per rank. The illustrated root receives P−1 full tensors sequentially. Posting receives concurrently changes scheduling, not the root’s total incoming payload.',steps:[['Keep the root’s contribution','Rank 0 starts the accumulator with its own tensor.'],['Receive one source at a time','Ranks 1, 2, and 3 send to the root in order. Each receive is added into the accumulator.'],['Finish without replication','The root is the only rank that gets the complete reduction; adding a broadcast would form an AllReduce.']],extra:'Simple and useful for explaining semantics, but a serialized root often becomes a bottleneck at larger group sizes.'}},
 scatter:{
  Direct:{cost:'T ≈ (P−1)α + (P−1)Nβ/P',costNote:'N is the root’s full input bytes. Equal destination slices are N/P bytes. This model matches the serialized root sends shown in the animation.',steps:[['Split the root input','Root holds [A, B, C, D], one destination slice per rank. It keeps A locally.'],['Send distinct slices','Root sends B to rank 1, C to rank 2, and D to rank 3. Each transfer carries N/P bytes.'],['Keep partitioned outputs','Ranks receive different data. The receiver layout is a partition of the root input, not four replicated copies.']],extra:'Root injection bandwidth limits total distribution. In-place API details determine whether original root storage remains available.'},
  Tree:{cost:'T ≈ Lα + (P−1)Nβ/P',costNote:'N is the complete root tensor size. For equal shards and power-of-two P, bundles along the critical path shrink N/2, N/4, …, N/P. This idealized tree assumes parallel independent links.',steps:[['Forward a destination bundle','Root sends [C, D] to rank 2, which becomes responsible for that subtree. Root retains [A, B].'],['Subdivide locally','Rank 0 forwards B to rank 1 while rank 2 forwards D to rank 3.'],['Assign canonical owners','Rank r ends with slice r. Packing and forwarding bundles can cost extra memory copies.']],extra:'The tree reduces startup depth, but intermediate ranks must receive and forward data not destined for themselves.'}},
 gather:{
  Direct:{cost:'T ≈ (P−1)α + (P−1)Nβ/P',costNote:'N is the full gathered output bytes at root. Each rank contributes N/P bytes. The demo serializes the root’s receives.',steps:[['Allocate the root destination','Reserve space for P equal shards and place root’s own shard at offset 0.'],['Receive by source','Receive the other shards into their rank-indexed slots. The input buffers on senders remain inputs, not defined output tensors.'],['Use the root’s concatenation','Only root has [A, B, C, D]. This preserves values and ordering; it does not add corresponding elements.']],extra:'Gather is suitable for coordinator-only outputs. AllGather is needed when every rank must access the complete result.'},
  Tree:{cost:'T ≈ Lα + (P−1)Nβ/P',costNote:'N is root’s complete output size. Tree bundles grow toward the root. The equal-shard, independent-link model omits pack/unpack overhead.',steps:[['Collect neighboring shards','Rank 1 sends B to rank 0; rank 3 sends D to rank 2.'],['Forward complete subtree bundles','Rank 2 sends [C, D] to root, preserving source order.'],['Finish the root buffer','Root combines [A, B] with [C, D]. Intermediate forwarding buffers are temporary, not additional final outputs.']],extra:'This reverses tree scatter’s dependencies. Root output memory still grows linearly with the number of input shards.'}},
 'all-to-all':{
  Pairwise:{cost:'T ≈ (P−1)α + (P−1)Nβ/P',costNote:'N is all outbound bucket bytes per rank, including the local bucket. Each remote peer receives N/P bytes in this equal-count example. The model assumes one send and receive can progress together.',steps:[['Keep the local bucket','Input cell s→d belongs at destination d. The cell r→r remains on rank r.'],['Rotate peer partners','In round k = 1…P−1, send to (r+k) mod P and receive from (r−k) mod P. This avoids requiring all peer messages to progress at once.'],['Transpose the ownership','Output at destination d is ordered by source: [0→d, 1→d, 2→d, 3→d]. No reduction occurs.']],extra:'At P = 4, three rounds exchange all off-diagonal buckets. Packing buffers and simultaneous network routes can dominate practical time.'},
  Direct:{cost:'Sent bytes/rank = (P−1)N/P; P−1 concurrent peer sends',costNote:'N is outbound bucket bytes per rank. Posting all peers does not guarantee one-round latency: injection limits, queue depth, link contention, and receive progress determine completion.',steps:[['Prepare every peer buffer','Pack an equal-sized slice for each destination and reserve a source-indexed receive buffer.'],['Post concurrent transfers','Issue matching sends/receives for all off-rank pairs. The animation shows all 12 directed transfers for four ranks.'],['Wait, then unpack','Consume the output only after all required peer operations complete. Preserve source ordering even if completion order differs.']],extra:'Potentially exposes more network concurrency than a pairwise schedule, at the cost of more active requests and possibly more contention.'}},
 'all-to-all-v':{'Count + payload':{cost:'Pack → exchange counts → transfer variable payloads → unpack',costNote:'Let Sᵣ and Rᵣ be rank r’s off-rank sent and received bytes. A rank-bandwidth lower bound is maxᵣ(max(Sᵣ,Rᵣ))β; metadata, startup, network cuts, and imbalance add cost. Counts are element counts, not necessarily bytes.',steps:[['Compute destination counts','Rank 0 has [1, 3, 0, 2] items for destinations 0–3. Exclusive prefix sums turn counts into buffer offsets.'],['Make send/receive counts agree','Source s’s count for d must equal destination d’s expected count from s. Exchange this metadata unless the application already knows it.'],['Exchange only nonempty buckets','Send exactly the packed count for each peer, then restore application ordering. Zero-count buckets contribute no items.']],extra:'The v means variable counts, not variable tensor datatype. For MoE, keep source/token indices so the return exchange can undo the dispatch permutation.'}},
 'send-recv':{Direct:{cost:'T ≈ α + Nβ',costNote:'N is the message payload bytes. This single-message model excludes rendezvous handshakes, registration, device readiness, and transport-progress overhead.',steps:[['Match the operation','Source, destination, communicator, datatype, and count agree. MPI adds message tags; NCCL grouping and operation ordering use different matching rules.'],['Transfer a ready buffer','A producer finishes before the send reads its data. The receive has valid storage and a compatible matching operation.'],['Wait before reuse','The sender may reuse storage and the receiver may consume data only after the relevant stream/event/request completion.']],extra:'Eager protocols buffer small messages; rendezvous protocols coordinate larger transfers before moving payload. “Nonblocking” describes API behavior, not guaranteed compute/network overlap.'}},
 barrier:{Dissemination:{cost:'After all enter: T ≈ ⌈log₂P⌉α (tiny signals)',costNote:'P is participant count. α represents small control-message startup; payload cost is negligible. Total observed wait also includes late arrival. A barrier does not make all ranks leave at precisely the same instant.',steps:[['Enter the same barrier','Ranks can arrive at different wall-clock times; an early rank waits. Each communicator member must participate.'],['Disseminate arrival knowledge','In round k, send to (r+2ᵏ) mod P and receive from (r−2ᵏ) mod P. Each round doubles the covered participant set.'],['Release after global entry','After enough rounds, completion implies every member entered. It says nothing about unrelated GPU streams unless the framework specifies additional synchronization.']],extra:'A missing participant or inconsistent collective order can hang the group. Barriers coordinate participation; they are not a replacement for correct data dependencies.'}},
 scan:{'Recursive doubling':{cost:'T ≈ ⌈log₂P⌉(α + Nβ)',costNote:'N is the per-rank input tensor size, not a gathered global tensor. The illustrated inclusive doubling scan sends a running prefix toward higher ranks. Local reduction cost is omitted.',steps:[['Start from the local input','Inclusive SUM on local scalars [1, 2, 3, 4] should produce [1, 3, 6, 10].'],['Combine ordered lower prefixes','At distance 1, then 2, receive the prefix from r−distance when that rank exists. Combine lower-rank operands before local operands for an order-sensitive operator.'],['Interpret inclusive versus exclusive','Inclusive includes the local value. Exclusive gives preceding-rank totals: [0, 1, 3, 6] for offsets, after explicitly setting rank 0’s undefined MPI Exscan result to zero.']],extra:'For local item counts [1,2,3,4], exclusive offsets [0,1,3,6] identify each rank’s non-overlapping segment in a 10-item global packed buffer.'}}
};
for(const t of topics.filter(t=>t.section==='communication')){
 t.algorithmDetails=ALGORITHM_LESSONS[t.id];t.notation=COMM_NOTATION;
 t.semanticNote={
  'all-reduce':'All input tensors describe the same positions. Add vertically, then replicate the sum; do not concatenate.',
  'all-gather':'Each input is a different piece. Copy those pieces into source-rank order on every rank.',
  'reduce-scatter':'Add matching positions across inputs, then assign a different output position range to each rank.',
  broadcast:'Only the root’s input is meaningful. Copy it unchanged to every participant.',
  reduce:'Add matching input positions. Only the root gets a defined output tensor.',
  scatter:'Only the root has the complete input. Partition it into different rank-ordered output slices.',
  gather:'Concatenate the distinct inputs at the root; non-root ranks have no defined gathered output.',
  'all-to-all':'Transpose ownership: source s’s destination-d bucket becomes destination d’s source-s output bucket.',
  'all-to-all-v':'Transpose variable-size buckets; counts and offsets determine how much each peer sends and where it lands.',
  'send-recv':'Copy one sender’s buffer to one matched receiver. Other ranks are uninvolved.',
  barrier:'No tensor is reduced or copied. Completion means all participants have entered this synchronization point.',
  scan:'Rank r receives the reduction of inputs 0 through r, preserving rank order. Each output covers a different prefix.'
 }[t.id];
}
