function selectedLesson(topic,option,mode){
 const base={formula:topic.formula,cost:topic.cost,costNote:topic.costNote,steps:topic.steps,notation:topic.notation||[],details:topic.details||[],comparisons:topic.comparisons};
 const variant=topic.algorithmDetails?.[option]||topic.variantDetails?.[option]||{};
 const result={...base,...topic.modes?.[mode],...variant};
 if(topic.section==='communication')result.details=[['The contract comes first',topic.semanticNote],['Selected implementation · '+option,variant.extra],...(topic.details||[]).filter(([title])=>title==='Backend support is separate from the contract')];
 if(topic.id==='broadcast'&&option==='Pipelined tree')result.notation=[...result.notation,['K, h','pipeline chunk count (4) and tree depth in links (2)']];
 if(topic.id==='all-to-all'||topic.id==='all-to-all-v')result.notation=[...result.notation,['s, d','source and destination rank indices'],['sendcount, recvcount','number of elements sent/received for a particular peer; offsets locate each bucket']];
 if(topic.id==='all-to-all-v')result.notation=[...result.notation,['Sᵣ, Rᵣ','total off-rank outgoing and incoming bytes for rank r']];
 return result;
}
